const rows = $json.data ?? [];

if (!Array.isArray(rows)) {
  throw new Error(
    'Respuesta inesperada de Directus'
  );
}

const now = new Date();

function contactLabel(contact) {
  if (!contact) {
    return 'Sin contacto';
  }

  const name = [
    contact.first_name,
    contact.last_name
  ]
    .filter(Boolean)
    .join(' ')
    .trim();

  if (contact.company && name) {
    return `${contact.company} · ${name}`;
  }

  return (
    contact.company ||
    name ||
    'Sin contacto'
  );
}

function dueState(task) {
  if (!task.due_at) {
    return {
      state: 'no_due_date',
      label: 'Sin fecha',
      sort_rank: 3,
      sort_time: Number.MAX_SAFE_INTEGER
    };
  }

  const due = new Date(task.due_at);

  if (Number.isNaN(due.getTime())) {
    return {
      state: 'invalid_due_date',
      label: 'Fecha inválida',
      sort_rank: 4,
      sort_time: Number.MAX_SAFE_INTEGER
    };
  }

  if (due.getTime() < now.getTime()) {
    return {
      state: 'overdue',
      label: 'Retrasada',
      sort_rank: 0,
      sort_time: due.getTime()
    };
  }

  const sameDay =
    due.getFullYear() === now.getFullYear() &&
    due.getMonth() === now.getMonth() &&
    due.getDate() === now.getDate();

  if (sameDay) {
    return {
      state: 'today',
      label: 'Hoy',
      sort_rank: 1,
      sort_time: due.getTime()
    };
  }

  return {
    state: 'upcoming',
    label: 'Próxima',
    sort_rank: 2,
    sort_time: due.getTime()
  };
}

const tasks = rows.map(task => {
  const due = dueState(task);

  return {
    id: task.id,

    title: task.title ?? null,
    description: task.description ?? null,

    status: task.status ?? null,
    priority: task.priority ?? null,

    due_at: task.due_at ?? null,
    due_state: due.state,
    due_label: due.label,

    source: task.source ?? null,

    created_at: task.created_at ?? null,
    updated_at: task.updated_at ?? null,

    contact: task.contact_id
      ? {
          id: task.contact_id.id,
          first_name:
            task.contact_id.first_name ?? null,
          last_name:
            task.contact_id.last_name ?? null,
          company:
            task.contact_id.company ?? null,
          email:
            task.contact_id.email ?? null,
          label:
            contactLabel(task.contact_id)
        }
      : null,

    _sort_rank: due.sort_rank,
    _sort_time: due.sort_time
  };
});

const priorityRank = {
  urgent: 0,
  high: 1,
  normal: 2,
  low: 3
};

tasks.sort((a, b) => {
  if (a._sort_rank !== b._sort_rank) {
    return a._sort_rank - b._sort_rank;
  }

  if (a._sort_time !== b._sort_time) {
    return a._sort_time - b._sort_time;
  }

  return (
    (priorityRank[a.priority] ?? 99) -
    (priorityRank[b.priority] ?? 99)
  );
});

const normalizedTasks = tasks.map(task => {
  const {
    _sort_rank,
    _sort_time,
    ...cleanTask
  } = task;

  return cleanTask;
});

const summary = {
  total: normalizedTasks.length,

  overdue:
    normalizedTasks.filter(
      task => task.due_state === 'overdue'
    ).length,

  today:
    normalizedTasks.filter(
      task => task.due_state === 'today'
    ).length,

  upcoming:
    normalizedTasks.filter(
      task => task.due_state === 'upcoming'
    ).length,

  no_due_date:
    normalizedTasks.filter(
      task => task.due_state === 'no_due_date'
    ).length
};

return [
  {
    json: {
      status:
        normalizedTasks.length === 0
          ? 'empty'
          : 'ok',

      summary,

      tasks: normalizedTasks
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const contactId = clean(input.contact_id);

if (contactId) {
  const uuidPattern =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  if (!uuidPattern.test(contactId)) {
    throw new Error(
      `contact_id no es un UUID válido: ${contactId}`
    );
  }
}

let limit = Number(input.limit ?? 50);

if (
  !Number.isInteger(limit) ||
  limit < 1
) {
  throw new Error(
    `limit inválido: ${input.limit}`
  );
}

limit = Math.min(limit, 100);

const filter = {
  status: {
    _eq: 'pending'
  }
};

if (contactId) {
  filter.contact_id = {
    _eq: contactId
  };
}

return [
  {
    json: {
      contact_id: contactId,
      limit,
      filter
    }
  }
];
